def register(page, ad, faq, leadbox, searchbox):
    R = "{R}"
    hub_cards = ""
    for c in CODES:
        hub_cards += f'<a class="card" href="{c["slug"]}.html"><span class="flag">{c["flag"]}</span><div class="pfx">{c["pfx"]}</div><h3>{c["h1"].split(":")[0]}</h3><p>{c["h1"].split(": ")[1]}</p></a>'
